/// <summary>
/// Summary setup data for report.
/// </summary>
class AVADAIReportService
{
    AVADAIParameters        parameters;
    AVADAIReport            reportSetup;
    Map                     dataSources;
    Map                     aliases;
    Map                     ignoreArchive;
    //report setup
    AVADAIReportMetadata    metadata;
    //document key
    TableId                 documentNumTableId;
    AVADAITableFieldMethod  documentNumFieldName;

}

Method.Source:
/// <summary>
///   init metadata and setup
/// </summary>
/// <param name = "_report">The report name.</param>
/// <param name = "_design">The design name.</param>
private void findRecord(AVADAIReportName _report, AVADAIReportDesign _design)
{
    AVADAIReportMetadataField   exportMetadata;
    Set                         fieldsMethods;
    str                         fieldMethod;

    if (AVADAIServer::findServer(parameters.ServerId).ExportActive == NoYes::No)
    {
        reportSetup.clear();
        return;
    }

    if (_report != reportSetup.Report && _design != reportSetup.Design)
    {
        //find report setup
        reportSetup = AVADAIReport::find(parameters.ServerId, _report, _design);

        //make metadata definition
        dataSources = new Map(Types::Integer, Types::Class);
        if (this.isDAIMetadataExport())
        {
            metadata = AVADAIReportMetadata::find(reportSetup.MetaDataId);

            while select exportMetadata
                    where exportMetadata.MetaDataId == reportSetup.MetaDataId
            {

                fieldMethod = exportMetadata.FieldMethod;

                //check document number
                if (exportMetadata.DocumentKey)
                {
                    documentNumTableId      = tableName2Id(exportMetadata.Table);
                    documentNumFieldName    = fieldMethod;
                }

                if (dataSources.exists(tableName2Id(exportMetadata.Table)))
                {
                    fieldsMethods = dataSources.lookup(tableName2Id(exportMetadata.Table));
                }
                else
                {
                    fieldsMethods = new Set(Types::String);
                }

                fieldsMethods.add(fieldMethod);

                if (exportMetadata.Alias)
                {
                    aliases.insert(strfmt('%1_%2', tableName2Id(exportMetadata.Table), exportMetadata.FieldMethod), exportMetadata.Alias);
                }

                //fill the map with all ignoreArchive
                if (exportMetadata.IgnoreArchive)
                {
                    ignoreArchive.insert(strfmt('%1_%2', tableName2Id(exportMetadata.Table), exportMetadata.FieldMethod), exportMetadata.IgnoreArchive);
                }

                dataSources.insert(tableName2Id(exportMetadata.Table), fieldsMethods);

            }

        }

    }

}

/// <summary>
///   init parameters
/// </summary>
protected void new()
{

    parameters      = AVADAIParameters::find();
    dataSources     = new Map(Types::Integer, Types::Class);
    aliases         = new Map(Types::String, Types::String);
    ignoreArchive   = new Map(Types::String, Types::Enum);
}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <param name="_report">The report to check</param>
/// <param name="_design">The design to check</param>
public void parmReport(AVADAIReportName _report, AVADAIReportDesign _design)
{
    this.findRecord(_report, _design);
}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <returns>
///  has data
/// </returns>
public boolean isDAIReport()
{
    return reportSetup.RecId != 0 && reportSetup.Active == NoYes::Yes;
}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <returns>
///   export report data
/// </returns>
public boolean isDAIMetadataExport()
{

    return reportSetup.ExportMetadata && (reportSetup.MetaDataId != '') && reportSetup.Active == NoYes::Yes;

}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <returns>
///   PDF archive
/// </returns>
public boolean isDAIReportExport()
{
    return reportSetup.ExportReport && reportSetup.Active == NoYes::Yes;
}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <returns>
///   
/// </returns>
public AVADAIReportMetadata getMetadata()
{
    return this.metadata;
}

/// <summary>
///   exported fields
/// </summary>
/// <returns>
///
/// </returns>
public Map getMetadataDefinition()
{
    return dataSources;
}

/// <summary>
///   exported fields
/// </summary>
/// <returns>
///  Alias information
/// </returns>
public Map getAliasesDefinition()
{
    return aliases;
}

/// <summary>
///   ignoreArchive 
/// </summary>
/// <returns>
///  map with als ignoreArchive 
/// </returns>
public Map getIgnoreArchiveDefinition()
{
    return ignoreArchive ;
}

/// <summary>
///   exported fields
/// </summary>
/// <returns>
///  document identification
/// </returns>
public Container getDocumentKey()
{
    return [documentNumTableId, documentNumFieldName];
}

/// <summary>
///   is report for DMS archive
/// </summary>
/// <returns>
///  report active
/// </returns>
public boolean isDAIEnabled()
{
    return parameters.Enabled;  
}

/// <summary>
///   report properties
/// </summary>
/// <returns>
///  export settings
/// </returns>
public AVADAIReport getReportSetup()
{
    return reportSetup;
}

/// <summary>
///   construct
/// </summary>
/// <returns>
///  <c>AVADAIReportService</c>
/// </returns>
public static AVADAIReportService construct()
{
    return new AVADAIReportService();
}
